ALTER TABLE "announcements" ADD COLUMN "content_document" jsonb DEFAULT '{"version":1,"blocks":[]}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "announcements" ADD CONSTRAINT "announcements_content_document_check" CHECK (case when jsonb_typeof("announcements"."content_document") = 'object' and jsonb_typeof("announcements"."content_document" -> 'blocks') = 'array' then "announcements"."content_document" -> 'version' = '1'::jsonb and jsonb_array_length("announcements"."content_document" -> 'blocks') <= 16 and octet_length("announcements"."content_document"::text) <= 30000 else false end);